// lookup demo — Labrador Retriever (jahdb demo program)
var DATA={"Labrador Retriever":"The Labrador is the world most popular breed: friendly, trainable, and endlessly fetch-driven. Needs lots of exercise and loves water."};
function lookup(q){q=String(q).toLowerCase();var h=[];for(var k in DATA){if((k+" "+DATA[k]).toLowerCase().indexOf(q)>=0)h.push(k+": "+DATA[k]);}return h.length?h.join("\n"):"no match for "+q;}
function listAll(){return Object.keys(DATA).join(", ");}
console.log("sample lookup:");console.log(lookup("large"));

